func (this *DefaultPassConfig) assertValidOrderForChecks(checks *PassListBuilder) {
	checks.assertPassOrder(this.declaredGlobalExternsOnWindow, this.checkVars_, "declaredGlobalExternsOnWindow must happen before VarCheck, which adds synthetic externs")
	checks.assertPassOrder(this.chromePass, this.checkJsDocAndEs6Modules, "The ChromePass must run before after JsDoc and Es6 module checking.")
	checks.assertPassOrder(this.closureRewriteModule, this.processDefinesCheck, "Must rewrite goog.module before processing @define's, so that @defines in modules work.")
	checks.assertPassOrder(this.closurePrimitives, this.polymerPass, "The Polymer pass must run after goog.provide processing.")
	checks.assertPassOrder(this.chromePass, this.polymerPass, "The Polymer pass must run after ChromePass processing.")
	checks.assertPassOrder(this.polymerPass, this.suspiciousCode, "The Polymer pass must run before suspiciousCode processing.")
	checks.assertPassOrder(this.addSyntheticScript, this.gatherModuleMetadataPass, "Cannot add a synthetic script node after module metadata creation.")
	checks.assertPassOrder(this.closureRewriteModule, this.removeSyntheticScript, "Synthetic script node should be removed only after module rewriting.")
	checks.assertPassOrder(this.closureRewriteModule, this.rewriteCallerCodeLocation, "ClosureRewriteModule must happen before RewriteCallerCodeLocation, so that exported functions and call sites are rewritten correctly.")
	checks.assertPassOrder(this.closureRewriteModule, TranspilationPasses_getEs6RewriteDestructuring(Es6RewriteDestructuring_ObjectDestructuringRewriteMode_REWRITE_ALL_OBJECT_PATTERNS), "RewriteCallerCodeLocation must happen before Es6RewriteDestructuring, because we need ReWriteCallerCodeLocation to run before default parameters get rewritten.")
	checks.assertPassOrder(this.closureRewriteModule, TranspilationPasses_getEs6RewriteDestructuring(Es6RewriteDestructuring_ObjectDestructuringRewriteMode_REWRITE_OBJECT_REST), "RewriteCallerCodeLocation must happen before Es6RewriteDestructuring, because we need ReWriteCallerCodeLocation to run before default parameters get rewritten.")
	if checks.contains(this.closureGoogScopeAliases) {
		Preconditions_checkState_boolean_Object(checks.contains(this.checkVariableReferences), "goog.scope processing requires variable checking")
	}
	checks.assertPassOrder(this.gatherModuleMetadataPass, this.closureCheckModule, "Need to gather module metadata before checking closure modules.")
	checks.assertPassOrder(this.gatherModuleMetadataPass, this.createModuleMapPass, "Need to gather module metadata before scanning modules.")
	checks.assertPassOrder(this.createModuleMapPass, this.rewriteCommonJsModules, "Need to gather module information before rewriting CommonJS modules.")
	checks.assertPassOrder(this.rewriteScriptsToEs6Modules, this.gatherModuleMetadataPass, "Need to gather module information after rewriting scripts to modules.")
	checks.assertPassOrder(this.gatherModuleMetadataPass, this.checkMissingRequires, "Need to gather module information before checking for missing requires.")
}

func (this *DefaultPassConfig) assertValidOrderForOptimizations(optimizations *PassListBuilder) {
	optimizations.assertPassOrder(this.j2clPass, TranspilationPasses_rewriteGenerators, "J2CL normalization should be done before generator re-writing.")
	optimizations.assertPassOrder(TranspilationPasses_rewritePolyfills, this.processDefinesOptimize, "Polyfill injection must be done before processDefines as some polyfills reference goog.defines.")
	optimizations.assertPassOrder(TranspilationPasses_injectTranspilationRuntimeLibraries, this.processDefinesOptimize, "Runtime library injection must be done before processDefines some runtime libraries reference goog.defines.")
	optimizations.assertPassOrder(this.processDefinesOptimize, this.j2clUtilGetDefineRewriterPass, "J2CL define re-writing should be done after processDefines since it relies on Compiler#getDefineNames to have been populated by it.")
	optimizations.assertPassOrder(this.removeUnusedCode, this.isolatePolyfills, "Polyfill isolation should be done after RemovedUnusedCode. Otherwise unused polyfill removal will not find any polyfill usages and will delete all polyfills.")
	optimizations.assertPassOrder(TranspilationPasses_instrumentAsyncContext, TranspilationPasses_rewriteAsyncIteration, "AsyncContext should be instrumentated before await and/or yield is transpiled away")
	optimizations.assertPassOrder(TranspilationPasses_instrumentAsyncContext, TranspilationPasses_rewriteAsyncFunctions, "AsyncContext should be instrumentated before await and/or yield is transpiled away")
	optimizations.assertPassOrder(TranspilationPasses_instrumentAsyncContext, TranspilationPasses_rewriteGenerators, "AsyncContext should be instrumentated before await and/or yield is transpiled away")
}

